	[220449] = "Ồ? Đây là làm sao？",
	[131075] = "1. Thời gian hoạt động，tẩy luyện đạt được số lần nhất định，sẽ nhận được một Tẩy Luyện Lệnh đặc biệt.\n2. Tẩy luyện đủ 25lần，sẽ thăng cấp Tẩy Luyện Lệnh. Có thể nâng 1 cấp cho tất cả kỹ năng của bộ trang bị màu tím, trang bị màu tím đầy cấp không thể dùng\n3. Tẩy đủ 60 lần，nhận được Tẩy Luyện Lệnh mật kỹ. Bộ màu tím kỹ năng cấp 5 3 sao có thể tẩy ra bộ màu tím kĩ năng mật kỹ 4 sao.\n4. Tẩy đủ 200 lần，nhận được tẩy luyện thần kỹ. Bộ màu tím kỹ năng cấp 5 3 sao có thể tẩy ra bộ màu tím kỹ năng mật kỹ 4 sao mà bạn đã chỉ định,\n5. Kết thúc hoạt động，Tẩy Luyện Lệnh không thể dùng，sẽ bảo tồn trong kho, bạn có thể tiếp tục sử dụng.",
