	[135518] = "1. Trong thời gian hoạt động có thể nhận Thần Đỉnh qua bảo thạch thương hội, dùng thần đỉnh để ôn dưỡng tinh thạch có thể tăng tốc độ tiến hóa của tinh thạch\n2. Cách lấy: nói chuyện với thương nhân trong bảo thạch thương hội để đổi, đổi đến số lần nhất định có thể nhận Thần Đỉnh\n3. Cấp Thần Đỉnh: tổng cộng 5 cấp, có thể đổi dần theo cấp 5 thương nhân trong bảo thạch thương hội\n4. Nhiên liệu ôn dưỡng: chia làm \"Lê Hoa Mộc\" và \"Ô Đàn Mộc\". Thần Đỉnh tăng 1 cấp, tặng miễn phí 100 Lê Hoa Mộc. Người chơi cũng có thể dùng vàng mua trực tiếp\n5. Thuyết minh nhiên liệu: \"Ô Đàn Mộc\" ôn dưỡng nhanh hơn \"Lê Hoa Mộc\"; tinh thạch ôn dưỡng càng nhiều, nhiên liệu tiêu hao càng nhiều",
