	[490002] = "1.Ngày 1-sơ loại: Mỗi trận 1 ván phân thắng bại, chọn ra 16 người lọt vào vòng đấu loại.\n2.Ngày 2-Đấu loại: 16 loại 8, 8 loại 4, mỗi trận 3 ván thắng 2, chọn ra 4 người vào chung kết.\n3.Ngày 3-Chung kết: Bán kết, chung kết, mỗi trận 5 ván thắng 3, chọn ra quán quân cuối cùng.\n4.Ngày 4-Tiệc Tranh Bá: 16 tuyển thủ tổ chức tiệc mừng, mọi người đều có thể vào, và nhận được phiếu điểm.\n5.Top 16 bắt đầu thi đấu, tuyển thủ bị loại, có thể xem người khác thi đấu, cổ vũ trợ uy để nhận thiệp mời.\n6.Kế sách: Trước khi bắt đầu mỗi trận, có thể dùng Kế Sách Văn Quan, kế sách sẽ tự động dùng khi thi đấu.\n7. Hai bên tử trận cùng lúc: Phe thủ chiến thắng",
