	["222026_buildingTech"] = "Xây",
	[136080] = "1.Dùng thuốc nổ có thể nổ khoáng mạch.\n2.Khoáng mạch càng sâu, cấp bảo thạch càng cao.\n3. Khoáng mạch khác nhau, cấp bảo thạch sinh ra cũng khác.\n4. Khi khoáng mạch chịu số lần nổ nhất định xong sẽ sụp đổ biến mất.\n5.Chỉ cần có khoáng mạch sụp đổ sẽ có thể đến tầng sau, thuốc nổ mỗi tầng thiết lập lại.\n6. Dùng chức năng 【Kích nổ toàn bộ】 sẽ không tiêu hao thuốc nổ, nổ hết toàn bộ khoáng mạch tầng này.",
