	[220334] = "Nếu ngươi không giết Mạnh Hoạch chồng ta thì ta theo ngươi？",
	["470001_yyl"] = "Nước %s và nước ta cùng chung lợi hại, quyết định liên minh cùng chống nước %s!",
	[215865] = "Công Huân Lệnh\nDùng xong phần thưởng BCH trong ngày giảm 50%% Công Huân cần dùng, phần thưởng tăng 50%%",
	[74045] = "Kiên Thủ Thần Thạch Tiến Hóa Quyển Trục",
	[83041] = "Quy tắc phó tướng: \n1. Đạt Lv120, đánh bại phó bản Tào Chân, nghiên cứu khoa kĩ phó tướng sẽ có thể chiêu mộ phó tướng. \n2. Khi chiêu mộ chủ tướng đầy, chiêu mộ tiếp sẽ tự động chiêu mộ phó tướng.\n3.Phó tướng chiêu mộ sẽ tự động đi theo chủ tướng thứ 4, khi chiêu mộ cần cho chủ tướng thứ 4 \n ở trạng thái nghỉ. \n4. Giải tán chủ tướng thì phó tướng đi theo sẽ tự động trả thành chủ tướng \n5. Trong giao diện phó tướng có thể nhấp nút đi theo chủ tướng để tiến hành thay đổi chủ phó và \n thao tác người đi theo. Hai thao tác này cũng cần võ tướng tương ứng ở trạng thái nghỉ ngơi. \n6. Phó tướng chỉ có một hàng lính, trở thành hàng lính thứ 5 của chủ tướng, giữ lại đặc tính \n vốn có của tướng lĩnh, nhưng không thể dùng chiến pháp \n7. Chủ tướng mượn binh cũng có 5 hàng lính. \n8. Chủ tướng mộ binh đồng thời cũng giúp phó tướng mộ binh.",
