	[135415] = "1.Trong event chọn vào phe khác, hết event, server mở lại, tự vào phe chọn.\n2.Trên Lv%s được đổi phe. Số người cùng phe càng nhiều, quà càng lớn.\n3.Khi dừng event, nếu XH gamer (từ cao xuống) quá số người thì ko đổi.",
