	[121104] = "Tướng quân đã có thể sai khiến ảo ảnh phá thành chiếm đất",
	[1440405] = "Hoàng Xỉ tiểu nhi, đến một người ta giết một người, đến hai người ta giết cả hai! Tướng quân，Quan Mỗ nói xin xuất trận lần nữa！",
	[320508] = "Chúc mừng tướng quân ghép bộ trang bị %s trước nhất.",
	[1440406] = "Quan tướng quân xuất mã,bao vây bạch mã，quân Viên Thiệu hòan tòan vỡ trận, đội chủ lực bị tan rã！",
	[130090] = "Tiệc Thanh Mai",
	[1440407] = "Toàn bộ quân Viên Thiệu rút khỏi Thương Đình！Quân ta tòan lực tiến công,bố trí mai phục quân địch, cố gắn đánh bại một lần！",
