	["450001_yyl"] = "Chia sẻ cho bạn bè",
	[320512] = "Có thể chiêu mộ",
	[215834] = "Phiếu nhập hàng\nSau khi nhận sẽ tự động dùng, miễn phí mua\ntất cả đạo cụ Sở Quân Nhu (Trừ đạo cụ Vàng), có hiệu lực 7 ngày",
