	[130006] = "thợ thần thiên công",
	[73004] = "Đổi tài nguyên",
	[190031] = "Trong chận đấu",
	["222610_seasilk"] = "Đảo lớn thế này chắc chắc nhiều kho báu đây.",
	[320513] = "Có thể nhận hình vẽ",
	[390004] = "Vào",
	["222603_seasilk"] = "Mời Thủy thủ\n1.Mời thành công 1 thủy thủ sẽ được mời tiếp\n2.Mời đủ thủy thủ mới có thể xuất phát\n3.Có thẻ nhận số lần mời miễn phí tại Bảng Công Huân\nĐường biển\n1.Mỗi lần đến 1 hòn đảo có thể lên đảo thám hiểm\n2.Có thể nhận Mảnh Bảo vật, Tơ Lụa, Túi gấm Tây Vực trên đảo\n3.Quà của mỗi hòn đảo sẽ X2, X3, X5\n",
	["157004_ayjc"] = "Panama",
	[211017] = "<Nhấp để khóa>",
	[490117] = "Chí Tôn tranh bá.%s",
	[135988] = "Mở X2",
	[135908] = "Phần thưởng：%s",
	[220302] = "Từ Hoảng tướng quân，ta chân thành mời ngài gia nhập quân ta!",
	[390005] = "Nhận thưởng",
	[215833] = "Đại quân Đổng Trác tấn công\n1.Thời gian quốc chiến, đại quân Đổng Trác mang theo nhiều tài nguyên đến\n2.Cả nước cùng thảo phả Đổng Trác, thắng lợi cho thể tóm được hắn\n3.Số roi nhận được sẽ căn cứ xếp hạng sát thương\n4.Căn cứ thứ tự trước sau bắt Đổng Trác, nhận được 6, 5, 3 EXP Quốc Gia\n\nGiải cứu Hán Hiến Đế\n1.Mỗi tối quốc chiến, Đổng Trác sẽ dẫn theo Hán Hiến Đế làm con tin\n2.Đánh bại Đổng Trác có thể giải cứu Hán Hiến Đế\n3.Giải cứu Hán Hiến Đế xong, có thể an ủi 50 lần, miễn phí 10 lần\n4.Dùng hết số lần an ủi, đưa Hán Hiến Đế về Kinh\n\nQuật Đổng Trác\n1.Sau khi bắt được Đổng Trác, có thể dùng roi đánh để nhận thưởng\n2.Mỗi ngày Đổng Trác sẽ giao ra quốc bảo khác nhau, khi đánh sẽ ngẫu nhiên nhận được\n\ncuồng nộ\n1.Mỗi lần đánh Đổng Trác, Cuồng Nộ+1, tích đầy sẽ rơi vào trạng thái cuồng nộ\n2.Ở trạng thái cuồng nộ, đánh Đổng Trác sẽ được thưởng gấp đôi\n3.Mỗi lần sau khi cuồng nộ, nhân đôi phần thưởng đánh 20 lần, sau đó tạo mới\n\nReset\n1.Tiêu hao Vàng và quốc bảo mỗi ngày đều reset vào 9:30 mỗi ngày\n2.Số lần an ủi và roi reset vào 9:30 mỗi ngày",
