	[136020] = "Xác nhận tốn %s Vàng thưởng võ tướng?",
	[320406] = "1. Người chơi TOP 16 mở tiệc kéo dài 1 ngày. \n2. Tất cả người chơi có thể dùng thiệp mời tham gia yến hội, tham gia yến hội có thể nhận phiếu điểm, 1 Yến Hội tiêu hao 1 tờ. \n3. Vào sảnh tiệc xong, chờ một lúc sẽ tự động khai tiệc, không đủ 10 người sẽ tự giải tán. \n4. Vào Yến Hội có mở Yến Tửu, khai tiệc xong sẽ nhận thêm phiếu điểm. \n5. Khai tiệc xong, căn cứ vào quốc tịch của tất cả người dự tiệc, có thể sẽ phát thêm phần thưởng phiếu điểm. \n6. Người chơi TOP 16 có thể tự mua Yến Tửu cho sảnh tiệc của mình, một bữa tiệc sẽ tiêu hao 10 hũ Yến Tửu. \n7. Người dự tiệc tham gia Yến Hội cò Yến Tửu cò thể nhận thêm phần thưởng phiếu điểm \n8. Kết thúc Yến Hội, căn cứ số người dự tiệc của mỗi sảnh tiệc, trong TOP 16 sẽ chọn ra người hấp dẫn nhất trong bữa tiệc. \n9. Căn cứ vào người hấp dẫn nhất bữa tiệc thì quốc dân của quốc gia trong máy chủ đó sẽ nhận được phần thưởng nhất định.\n",
	[217308] = "Căn cứ tửu lượng của võ tướng tăng độ say",
