	[135872] = "Thỏ ngọc:%s",
	[1448022] = "Chúng ta cần đi tìm Điêu Thiền trước nói Điêu Thiền thuyết phục Lữ Bố giúp đỡ.",
	[136394] = "Xe Gỗ\n1.Người chơi cả nước tham gia Quốc Chiến, cùng nhau cướp đoạt Xe Gỗ nước địch.\n2.Khi đủ số Xe Gỗ, bước vào giai đoạn phát quân tư, nhận được 3 Xe Gỗ và số lần nhận thưởng tiếp.\n3.Số lần nhận thưởng tích lũy cả ngày, mỗi ngày 0h reset\n4.Vòng 1 phát quân tư kéo dài đến 8h sáng mỗi ngày.\nPhần thưởng\n1.Mỗi Xe Gỗ có thể mở ra Quân tư thường và Quân tư đặc biệt.\n2.Quân tư đặc biệt mỗi ngày không giống nhau.",
	[1448021] = "Đổng Trác vẫn chưa đến Anh Cung bái kiến thiên tử，đây là cơ hội tốt diệt trừ gian thần.",
	[216309] = "(Chiếm thành xong có thể bế quan)",
	[136396] = "Tốn Vàng phát quân tư",
	[1448004] = "Tướng quân tiến quân chậm, Lưu Hoàng thúc rơi xuống nước bị quân địch bắt được.",
