	["143032_qym"] = "Dùng vàng mua thời gian thám bảo",
	[1448041] = "Nam Quận là nơi quân ta phải dành, chúng ta không được qui phục phải  Đem được Tôn Ngô,xin tướng quân giúp quân ta chiếm lĩnh Nam Quận",
