	[370004] = "Công Thành Xa lv1",
	[136863] = "Cần 500 EXP Quốc Gia\nThần binh đạt LV150 mới được tham gia\n(Cần trưng mộ 1 thần tướng Trân Bảo 9.2)\nSau khi thông qua có thể nhận tiếp EXP Quốc Gia",
