	[1440400] = "Tướng quân，quân ta hiện cùng với quân Tào Tháo kề vai sát cánh chiến đấu, đều định ở lần này.",
	[215313] = "Chiếu chỉ: %s/%s",
	[370003] = "Hoa Hùng",
	[135643] = "Quan Vũ",
	["220710_qixie"] = "Khởi bấm tướng quân! Vừa này chiến xa địch trong chiến đấu chính là 【Tịch Lịch Đầu Thạch Xa】do Lưu Diệp cải tạo trong trận Quan Độ!",
