	[136364] = "Ăn Bánh Trôi được",
	[220763] = "Ta phải đánh bại Đông Doanh để lấy ngọc tỷ mới có thể đánh Tào.",
	[220278] = "Tướng quân không cần nói nhiều, ngài là đại anh hùng, lão Điển ta bái phục!!",
	["222037_buildingTech"] = "Xác nhận chuyển nghề thành thợ mộc?",
	[1440801] = "Tướng quân，đây là doanh trại lớn của ta, mục tiêu lần này cùng với quân Lưu Bị đánh chiếm Bái Môn Lâu",
	[130071] = "Hoạt động Nguyên Tiêu",
	[1440802] = "Nơi này còn có doanh trại lớn cô độc, mục tiêu chung là Bái Môn Lâu! Chiếm trước！",
	["216417_qxgj"] = "%s thế lực",
	[1440803] = "Tướng quân nhất định cần nhanh chóng chiếm lĩnh Bái Môn Lâu giữa Quân Tào, nếu không sẽ kết thúc thất bại.",
	[20050] = "Hôm nay còn lại：%s lần",
	[1440804] = "Theo tin tức đáng tin cậy, bộ đội quân Tào mỗi cách đoạn thời gian sẽ tiến quân về Bái Môn Lâu.",
	[220774] = "Nghe nói thủ tướng Phàn Thành-Tào Nhân có sức mạnh vô song!",
	[1440805] = "Chỉ cần quan sát tốt tình hình chiến sự, lợi dụng hợp lý bộ đội quân Tào, đánh chiếm Bái Môn Lâu sẽ dễ như trở bàn tay.",
	[216305] = "Thành trì sửa đường (%s)",
	[1440806] = "Thật là nực cười, Bái Môn Lâu há là bọn ngươi chiếm giữ, hãy mang quân ngựa đến đây đi！",
	["143035_qym"] = "Tốn Vàng mời Thủy thủ",
	[1440807] = "Tướng quân，mục tiêu lần này tương đồng với nền tảng đơn giản, ta lại nói quá lời rồi",
	[1440808] = "Sau đó lại nói một câu, lần này lại có nhiều quý nhân giúp đở, cố gắng！",
	[135371] = "Nhấp ăn bánh ú, ai sẽ ăn nhiều nhất",
	[1440809] = "Tướng quân, mục tiêu lần này vẫn như cũ không thay đổi, nhưng  có quý nhân phải tiến cử ngài.",
	[136367] = "Đã dùng hết số lần!",
	[1440810] = "Bì nhân thông thạo kỹ thuật đào sông",
	[136580] = "Ngài trở về rồi, Tiểu Kiều có tin tốt cho ngày đây!",
	[1440811] = "Có thể thông con sông Quảng Lăng Bắc với Đàm Thành. Ngăn chặn đường rút của Bái Môn Lâu.",
	[136583] = "Ngoài ra, nó còn giúp ngài gia tốc phong đất! Tướng quân hãy thử thao tác",
	[1440812] = "Quá tốt rồi, tướng quân nếu có yêu cầu, đừng quên đi Từ Châu tìm Quách Gia.",
