	[136577] = "Huân chương Vương Triều LV4",
	[136579] = "Tướng quân hãy chăm chỉ kiến tạo Thế Giới, hàng tấn công huân đang chờ!",
	[490142] = "1. Tống Qua Vệ: Dùng Bảo Thạch thông thương nhận Tơ Lụa.\n\n2.  Tra Nhĩ Lộc: Dùng Đá Thức Tỉnh thông thương nhận Tơ Lụa, mỗi lần tiêu hao 1 Đá Thức Tỉnh.",
