	[136518] = "Phát huy hiệu quả Tỉnh Táo, xin ngài hãy cho phép ta bắt đầu thức tỉnh!",
	[220369] = "Khổng Minh tiên sinh khách sáo rồi, xin hỏi Lưu Bị tướng quân có đây không？",
