	[136517] = "Mỗi lần thức tỉnh Gia Cát Lượng chỉ cần %s Rượu Thức Tỉnh",
	[1440814] = "Chỉ cần tướng quân hạ lệnh một tiếng, ta sẽ gào hét phía trước,Quang Lăng Đại Kiều Tinh anh trinh sát tùy cơ dẹp sạch Bái MÔn Lâu！",
	["157031_ayjc"] = "Iran",
	[1440815] = "Trương Phi thật sự một lòng trung thành, tướng quân có thể biết người sử dụng tốt hơn. Nghe nói Hạ Phi có động tĩnh, cùng đi xem thử.",
	[142014] = "Còn cần nạp thẻ:",
	[1440816] = "Bái Môn Lâu không được an tòan, hay là Tương Mĩ Thiếp Điêu Thiền sắp xếp như vậy.",
	[136544] = "Hãy chiêu gọi 1 tướng có Hổ Báo Kỵ, chuẩn bị quyết chiến Đông Doanh!",
	[220276] = "Được...được thôi, ta sau này không dám nói bừa nữa……",
	[136546] = "Khi mở đăng ký viễn chinh mới được ra trận",
	[1440818] = "Tướng quân, Lữ Bố xuất binh cứu Điêu Thiền rồi!Bái Môn Lâu phòng thủ tinh anh khuynh sào bắt tay điều động. Xin nhất thiết phải giữ bọn họ！",
	[91009] = "Nước Ngụy",
	[1440819] = "Không xong rồi, Lữ Bố cứu ra Điều Thiền, Tinh Anh Thủ phòng trở về Bái MÔn Lâu rồi！",
	["222120_juexingJiu"] = "Mua mỹ tửu",
	[1440820] = "Đào sông thành công！Bái Môn Lâu thông xuống đường Hạ Phi, bị nước ngập không có cách nào qua được.",
	[213305] = "Ngòi nổ đã chuẩn bị xong, hãy bắt đầu rèn!",
	[136592] = "Dám làm càn tại địa bàn ta, ai là tướng lĩnh, mau ra quyết chiến với ta!",
	[135862] = "Tinh luyện tiếp %s lần nhận tinh luyện miễn phí",
	[1440822] = "Bái Môn Lâu trong tay, lần này bạn đã thắng rồi！",
	[136590] = "Ngài chỉ cần chiếm thành này, gián điệp sẽ giúp ngài lập quân đoàn chiếm Cao Ly!",
	[1440823] = "Tin tức đáng tin cậy, Tào Tháo ngự giá thân chinh lần thứ 3! xin nhanh chóng tiến vào Bái Môn Lâu trước anh ta.nếu không có thể sẽ thua đấy!",
	[1440824] = "Tin tức đáng tin cậy, Quân Tào Tháo ngự giá thân chinh lần thứ 4! xin nhanh chóng tiến vào  Bái Môn Lâu trước anh ta, nếu không có thể thua đấy.",
	[136596] = "Đại vương, quân địch quá tàn bạo, ta đi trước đây!",
	[1440825] = "Tin tức đáng tin cậy，quân Tào Tháo ngự giá thân chinh lần thứ 6！xin nhanh chóng tiến vào Bái Môn Lâu trước anh ta, nếu không có thể sẽ thua đấy.",
	[136597] = "Nô gia... Nô gia không ổn rồi... Đại vương... Cẩn thận.",
	[220275] = "Ngươi đi giết địch đi, ta yêu cầu không cao, giết xong về tìm ta。",
	[135365] = "Bánh ngon! Bánh ngon!",
	[1440827] = "Các bạn người đông, ta vì mạnh phải hạ thủ trước！",
	[136595] = "Cao Ly Quốc, chả lẽ sẽ bị hủy hoại trong tay ta ư?",
	[1440828] = "Lính trinh sát Tinh Anh nghe lệnh! Để ta cố thủ Từ Châu Tiểu Kính",
	[100009] = "Khai quang",
	[136854] = "Ngoại địch sắp xâm phạm, hãy theo ta mở màn Lưu Cầu!",
	["155025_gcldhw"] = "Xếp hạng cuối cùng:",
	[490139] = "Nhắc nhở thông thương",
	[220771] = "Tướng quân mưu trí vô song, tại hạ xin thua!",
	[320350] = "Thuyết minh kĩ năng tinh thạch：\n  1.Tất kĩ kĩ năng tinh thạch max cấp 5, cấp càng cao, hiệu quả càng tốt.\n  2.Tất cả hiệu quả kĩ năng tinh thạch đều có thể cộng dồn, số lượng càng nhiều, hiệu quả càng tốt.\n  3.Cường Tập: tăng lực chiến phe công.\n  4.Kiên Thủ: tăng lực chiến phe thủ.\n  5.Vô Song: khi khiêu chiến cá nhân tăng lực chiến.\n  6.Trảm Sát：có tỉ lệ nhất định giết ngay 1 hàng quân địch.\n  7.Bạo kích: có tỉ lệ nhất định tăng gấp đôi sát thương chém giết.\n  8.Loạn Vũ: có tỉ lệ nhất định tăng mạnh sát thương chiến pháp.\n  9.Kiên nhẫn: có tỉ lệ nhất định nhận được chiến pháp giảm một nửa sát thương.",
