	hw_kfmg_000036 = "Đột nhập thành nước ta",
	["222130_juexingJiu"] = "Nhận Mỹ Tửu\n1.Nhận Mỹ Tửu tại sự kiện thế giới\n2.Dùng Vàng mua Mỹ Tửu tại giao diện hoạt động, phẩm chất ngẫu nhiên\n\nTiệc Đối Ẩm\n1.Tổ chức hoặc tham gia tiệc đều phải tốn 1 Mỹ Tửu\n2.Uống rượu trong yến tiệc để tăng thêm Say\n3.Khi phẩm chất Mỹ Tửu của cả hai giống nhau sẽ nhận được Rượu Thức Tỉnh\nMời khách quý\n1.Tào Tháo, Gia Cát Lượng hoặc Chu Du sẽ đem theo cùng loại rượu đến dự tiệc\n\nSay\n1.Rượu Thức Tỉnh dùng để thức tỉnh 1 lần\n2.Khi tiến độ Say đầy sẽ được hiệu quả Say Ngà (dùng Rượu Thức Tỉnh mới hiệu quả)\n3.Rượu Thức Tỉnh và Say Ngà chỉ áp dụng vào hoạt động lần này, quá hạn sẽ vô hiệu.",
	["222131_juexingJiu"] = "1.Trong bản đồ thế giới có thể nhận các loại mỹ tửu.",
	["222132_juexingJiu"] = "2.Dùng Vàng mua mỹ tửu, chủng loại ngẫu nhiên.",
	[220260] = "Ngươi đem hết binh khí ra đây trước, bộ dạng bủn xỉn bây giờ thật mất mặt……",
	["222134_juexingJiu"] = "1.Cử hành yến tiệc và tham gia yến tiệc đều tiêu hao 1 phần mỹ tửu.",
	[135350] = "%s，sản xuất ở Tương Dương",
	["222136_juexingJiu"] = "3.Khi hai người mỹ tửu cùng loại co thể nhận được Thức Tỉnh Tửu.",
	["222137_juexingJiu"] = "Mời khách quý",
