	[215036] = "Yến tiệc\n1.Phát thiệp mời 3 võ tướng dự tiệc nhận Quà Mừng\n2.Phẩm chất tướng dự tiệc càng cao, Quà Mừng càng nhiều\n3. Có 3 tướng cùng màu đến dự tiệc cùng lúc đạt combo, sẽ nhận thêm Quà Mừng đặc biệt\n4.Có thể mời 4 võ tướng cùng lúc, tăng tỉ lệ combo\nLevel Không Khí bữa tiệc\n1.Mỗi lần đạt combo sẽ tăng thêm Không Khí, càng nhiều tướng cùng màu, Không Khí tăng càng cao\n2.Tích lũy đạt 300, 600, 1200 Không Khí, có thể nâng cấp Không Khí\n3.LV Không Khí càng cao, phẩm chất tướng có thể mời càng cao\n4.Khi nâng cấp Không Khí, sẽ có 1 phần quà\nHậu Lễ\n1.Khi đạt combo tướng Vàng, nhận được Hậu Lễ hôm nay\n2. Tướng Vàng và hậu lễ của mỗi ngày đều khác nhau",
