	[72001] = "Dùng :",
	[91020] = "Chúc mừng chủ nhân lên làm quốc vương! Ngoài phúc lợi tài nguyên hàng ngày tăng thêm ra, ngài hiện giờ còn có thể biên tập thông báo quốc vương đấy!",
	[215304] = "Tiêu hao %s Vàng mua và phái thuyền?",
	[220224] = "Hắn nói xin ngài nghiên cứu khoa kĩ, hắn sẽ đến chợ bán Thiết cho ngài!",
	[136462] = "Đánh thành Thế Giới để bắt gà con, cho ăn 3 giờ sau sẽ trưởng thành, tăng cân\nCó thể dùng Vàng mua gà trưởng thành\n20h mỗi ngày dâng gà tế bái tổ tiên sẽ có quà, vật tế càng nặng, thưởng càng nhiều\nCó thể tốn Vàng để tế bái nhiều lần, nhận nhanh quà cao nhất\n3 ngày tế bái xong tất cả, sẽ được báu vật \"Truyền Nhân Rồng\"",
