	[20044] = "Lv97 Xưởng thuật sĩ cấp 4, xuất hiện thuật sĩ mới: có thể tự động nhận, nghiên cứu mượn binh thuật.",
	[135329] = "Độ đói：",
	expand1 = "Haha, chúng ta đã mở rộng lãnh thổ! Chiến tích này, sao có thể thiếu phần của tướng quân!",
	[1210904] = "Đủ LV220 tăng Hổ Báo Kỵ",
	[490083] = "1.1.Ngày 1-sơ loại: Mỗi trận 1 ván phân thắng bại, chọn ra 16 người lọt vào vòng đấu loại.\n2.Ngày 2-Đấu loại: 16 loại 8, 8 loại 4, mỗi trận 3 ván thắng 2, chọn ra 4 người vào chung kết.\n3.Ngày 3-Chung kết: Bán kết, chung kết, mỗi trận 5 ván thắng 3, chọn ra quán quân cuối cùng.\n4.Trợ uy Võ Đấu Hội: Top 16 bắt đầu thi đấu, tuyển thủ bị loại, có thể xem người khác thi đấu, cổ vũ trợ uy để nhận thưởng.\n5.Kế sách: Trước khi bắt đầu mỗi trận, có thể dùng Kế Sách Văn Quan, kế sách sẽ tự động dùng khi thi đấu.\n6.Kết thúc chiến đấu có thể chúc mừng quán quân, tiệc mừng chỉ kéo dài 1 ngày.\n7. Hai bên tử trận cùng lúc: Phe thủ chiến thắng",
