	[215310] = "Tranh công",
	[1440000] = "Hoan nghênh bạn đến Dốc Trường Bản！Hiện tại đại quân Tào Tháo tiến sát，nước ta ẩn thủ ở thành này!",
	[421027] = "Trong liên máy chủ không thể luyện binh",
	[1440001] = "Chiến trường hỗn loạn，A Đẩu lại hôn mê như thế này, mời tướng quân đột phá vòng vây, cứu A Đẩu!",
	expand2 = "Thu phục đất đai không phải chuyện một sớm một chiều, hãy tiếp tục nỗ lực!",
	[1440002] = "Tướng quân mời chú ý，doanh binh quân Tào thiết lập tại đây，không ngừng phái viện quân，Tiểu Thiến kiến nghị ngài nên đánh vào thành trước！",
	[135326] = "Chế tác",
	[1440003] = "Tay cầm Thanh Giang, bá chiếm thiên hạ, bảo kiếm của thừa tướng chính là sức mạnh này!",
	[215400] = "Sở Quân Nhu",
	[1440004] = "Tướng quân，Trương Hợp đột nhiên xuất hiện，chiếm giữ doanh binh，mời ngài nhanh chóng đánh đuổi！",
	[136815] = "%s %s quốc",
