	[220220] = "Tướng quân mau xem, bên kia có nhiều voi quá, đẹp quá!",
	[1440006] = "Mạc Hoảng tướng quân，ngài đánh vào thành này，ta thấy nên hủy bỏ kế hoạch nhỏ của Trương Hợp này đi！",
	speicalBuffInfo1 = "Đã kiến quốc",
	[1440007] = "Tướng quân，muốn cứu A Đẩu phải thông qua Bắc bình nguyên trước, doanh trại Tào sẽ phái binh chi viện Bắc Bình nguyên",
	[1440008] = "Kiến nghị bạn nhanh chóng bao vây doanh trại quân Tào, sau đó giải cứu，dựa vào đó có thể giúp đỡ bạn con đường an tòan!",
	[100008] = "Giá bán",
	[1440009] = "Tướng quan，trinh thám Cương Cương đến báo，phu nhân Lưu Bị tướng quân bị bất tỉnh ở doanh Tào, mời ngài nhanh chóng cứu viện！",
	["221006_buildNation"] = "Đúng vậy! Lần kiến quốc này cũng có công của ngươi!",
