	[220716] = "Tiểu thư hiểu nhầm rồi, ta là %s",
	[180013] = "Xin",
	[214302] = "Tại bất kỳ địa hình, phong đất đều sản sinh nguyên liệu Ngự Bảo màu đỏ,\n vàng, lục",
	[214303] = "Chi tiêu liên quan đến Ngự Bảo tất cả -20%% (Trừ nạp tiền)",
