	[136857] = "Quân ta sẵn sáng ứng chiến, đạt yêu cầu thần binh xin hãy xuất chinh Lưu Cầu!",
	[136814] = "Tướng có thần binh trên LV100 hãy toàn lực xuất kích, cố thủ Giao Chỉ!",
	[136510] = "Nhận Mỹ Tửu\n1.Nhận Mỹ Tửu tại sự kiện Thế Giới\n2.Tốn Vàng mua Mỹ Tửu tại giao diện Họa Động, phẩm chất ngẫu nhiên\n\nTiệc Đối Ẩm\n1.Tổ chức tiệc và tham dự tiệc đều tốn một số Mỹ Tửu\n2.Uống rượu tại yến tiệc sẽ tăng Túy Ý\n3.Khi phẩm chất Mỹ Tửu của 2 người giống nhau, sẽ nhận được Rượu Thức Tỉnh\n4.Mời khách quý: Gia Cát Lượng sẽ đem cùng loại rượu đến dự tiệc\n5.Khi uống Rượu Hùng Hoàng, sẽ được gấp đôi Rượu Thức Tỉnh\n\nTúy Ý\n1.Dùng Rượu Thức Tỉnh để thức tỉnh 1 lần\n2.Khi thanh tiến độ Túy Ý đầy, sẽ nhận được hiệu quả Say Ngà (Dùng khi thức tỉnh mới hiệu quả)\n3.Rượu Thức Tỉnh và Túy Ý chỉ có hiệu lực trong thời gian hoạt động kỳ này diễn ra.",
	[220219] = "Chúc Dung đã diệt, đâu ra thương nhân gì đó? Trần Cung quả nhiên không đáng tin, chết không hết tội!",
