	[491070] = "Luyện Xung Đột (%s)",
	[83048] = "Kế sách Đấu Võ: %s",
	[136409] = "Lì xì trời ban\n1. Người chơi cả nước cùng đánh công huân, tích lũy Hỷ Khí.\n2. Hỷ Khí đầy, sẽ có Lì xì trời ban 1 lần, nhận được lì xì thần tài và cơ hội đổi vận.\n3. Cơ hội đổi vận sẽ tích lũy cả ngày, mỗi ngày 0h reset.\n4. Vòng 1 Lì xì trời ban mỗi ngày kéo dài đến 8h sáng.\nThể lệ phần thưởng\n1. Mỗi bao lì xì có thể mở ra phần thưởng thường hoặc phần thưởng Thần tài gõ cửa.\n2. Phần thưởng thường của mỗi vòng Lì xì trời ban sẽ khác nhau.\n3. Phần thưởng Thần tài gõ cửa trong ngày giống nhau, khác ngày thì phần thưởng Thần tài gõ cửa cũng khác.",
	[220706] = "Hứa Chử ngươi đi cứu hỏa trước, để ta ngăn đám tặc tử này.",
