	[135218] = "Tốn %s Vàng\nnhận được %s Vẫn Thạch",
	[154114] = "Lưu Quang Phù",
	[136289] = "Thể lệ:\n1. Trước 21h hôm đầu event được vào trận luyện tập 5 lần, chung kết diễn ra vào 21h45, kéo dài 10p.\n2. Đối thủ trận luyện tập là NPC, sau đó tất cả người chơi sẽ PK nhau trong trận chung kết.\n3. Xe có trên 10 Tuần Lộc có thể xuất phát, càng nhiều tuần lộc tốc độ càng nhanh!\n4. Khi trượt sẽ gặp phải bóng tuyết, bị ném trúng sẽ dừng lại (nhấp xe tuyết liên tục 5 lần để đi tiếp); Nhấp đánh vỡ bóng tuyết.\nGiải thưởng:\n1. Quà 2 lần đầu của trận luyện tập là Rương Bạc, lần cuối là Rương Kim.\n2. Top 10 Chung Kết sẽ nhận được Rương Kim, còn lại nhận được Rương Bạc.\n2. Trận đấu kết thúc, thứ hạng càng cao được càng nhiều rương!\n4. Rương Bạc mở ra ít Thép Bách Luyện/Thép, Rương Kim mở ra nhiều Thép Bách Luyện/Thép.\n5. Người chơi tham gia Chung Kết đều nhận được 1 Bảo Vật Giáng Sinh, thứ hạng càng cao, phẩm chất bảo vật càng tốt.",
