	NpcHuangJin1_3 = "Hoàng Cân dư đảng quá nhiều, công phá thành trì có khóa sắt bảo vệ mới chiếm được chủ thành!",
	[218128] = "Nam Chiêu có 3 cửa ải, mỗi cửa đều có 1 vị tướng Nam Chiêu trấn giữ, phòng ngự nghiêm ngặt, phải mở hết khóa sắt mới vào được ải!",
	[218129] = "Binh sĩ bôn ba đường dài không thể đột kích đô thành, bạn cần chiếm 1 trong 3 cửa ải làm trạm trung chuyển",
	[136271] = "Miễn phí",
	["223314_luomu"] = "Hãy cải tạo Bụi Dâu 1 trước",
	[490059] = "TOP 8",
	[220665] = "Bắt đầu từ đây, Oanh Lôi Thuật và Lạc Lôi Thuật trong phó bản đều sẽ tính nhầm, xin chúa công chuẩn bị trước.",
	["217316_zww"] = "Bồ Đào Tửu",
	[95012] = "Xếp hạng hiện tại:",
	[200326] = "Nói rõ:\n quan viên nhất phẩm có thể phát động Man Tộc, sau khi phát động tăng độ thân mật.",
	[217205] = "Kiên thủ thành trì\n1.Phá nát chiến xa phe địch nhận được Vẫn Thạch trọng lượng 1-10\n2.Nếu trọng lượng Vẫn Thạch nhận được vượt quá tải trọng, chỉ thu về 10 Vẫn Thạch.\n3.Nếu trọng lượng vẫn thạch là 20, thưởng thêm 5 Vẫn Thạch.\n4.Nếu trọng lượng Vẫn Thạch vừa bằng tải trọng, được thưởng gấp 3.\nVương Bài Chiến Xa\nTấn công Vương Bài Chiến Xa của phe địch sẽ nhận được Lõi Vẫn Thạch, trọng lượng cố định là 7đ.",
	[40110] = "<font color='#D9CC90'>【Kịch bản】: </font>",
