	["216319_zww"] = "Tìm thêm %s chiếc chiến xa \nđịch quốc nữa được nhận thưởng!",
	[136269] = "Quy tắc:\n1. Trước 21h hôm diễn ra event có thể vào Trận Tập Luyện 3 lần, chung kết bắt đầu lúc 21h45, kéo dài 10p.\n2.Đối thủ ở Trận Tập Luyện là NPC, tất cả người chơi trong server sẽ đấu với nhau tại chung kết.\n3. Thuyền có trên 10 thủy thủ có thể xuất phát, thủy thủ càng nhiều, tốc độ càng nhanh!\n4.  Sau khi bị bèo quấn lấy thuyền làm đứng im, nhấp vào thuyền liên tục 5 lần để đi tiếp; Nhấp để xóa bèo.\nPhần thưởng:\n1. Dựa vào xếp hạng lộ trình để phát rương, XH càng cao, rương càng nhiều.\n2. %s.\n3. Người chơi tham dự chung kết đều được 1 báu vật, thứ hạng càng cao, phẩm chất báu vật càng tốt.",
