	["216324_zww"] = "1. Mỗi nhóm có 2 chiếc xe ngựa, 1 xe ngựa thường và 1 xe quân tư địch quốc, tìm được quân tư địch quốc có thể nhận thưởng Vẫn Thạch cố định\n2. Tổng cộng có 4 cổng thành, càng về sau phần thưởng xe ngựa thường càng phong phú\n3. Cổng thành bắc có thể mở thoải mái, nhưng phần thưởng không tăng\n4. Có thể chọn tăng thêm người khi chưa bắt đầu tìm kiếm mỗi nhóm, 1 lần tìm 3 chiếc xe ngựa\n5. Mỗi nhóm xe ngựa được miễn phí tìm 1 lần, sau đó có thể chọn nhóm kế hoặc nhóm này để tìm lần nữa\n6. Cứ tìm được 20 cỗ xe quân tư địch quốc, có thể nhận——Mảnh Khóa Khổng Minh",
