	[170009] = "Mã tặc",
	["166011_jc"] = "Đã dự đoán:",
	[490904] = "Tiến độ",
	["166012_jc"] = "Trong thời gian event, mỗi ngày có thể dự đoán trận đấu của ngày hôm sau.\nCược Bảo Thạch 1 sao để dự đoán, mỗi mục có bội số trúng khác nhau, chữ số bên phải khung chọn là bội số\nSau khi trúng dự đoán, sẽ phát thưởng Bảo Thạch 1 sao dựa theo bội số. Dự đoán trật sẽ không trả Bảo Thạch đã đặt cược.\nSau khi kết thúc trận đấu, căn cứ kết quả trận đấu để phát thưởng Bảo Thạch 1 sao, đặt cược càng nhiều, được thưởng càng nhiều.\nThời gian mỗi lần dự đoán là 0h-24h ngày hôm trước\nTrong thời gian đặt cược, có thể đặt cược các mục khác nhau nhiều lần\nMỗi mục đặt cược tối đa là 1000",
