	[95049] = "2",
	["155045_gcldhw"] = "Quy tắc:\n1.Trước 21h hôm event có thể vào giải luyện tập 3 lần, 21h30 sẽ bắt đầu chung kết, kéo dài 10 phút\n2.Đối thủ luyện tập là NPC, còn chung kết sẽ là trận so tài giữa tất cả người chơi của server đó\n3.Trên 10 Tuần Lộc có thể xuất phát, Tuần Lộc càng nhiều, tốc độ càng nhanh!\n4.Khi trượt sẽ gặp Bóng Tuyết, bị ném trúng sẽ dừng đi tiếp, nhấp vào để làm vỡ bóng\nPhần thưởng:\n1.2 phần thưởng đầu của giải luyện tập là Rương Bạc, cuối cùng là Rương Kim.\n2.Top 10 Chung Kết sẽ được Rương Kim, giải tham dự là Rương Bạc\n3.Thứ hạng càng cao, số rương càng nhiều\n4.Rương Bạc sẽ mở ra Thép Bách Luyện/Thép, Rương Kim mở ra nhiều Thép Bách Luyện/Thép hơn\n5.Người chơi tham gia chung kết đều có 1 vật kỷ niệm Giáng Sinh, thứ hạng càng cao, vật phẩm càng tốt.",
