	[92141] = "Mở Kiến Tạo sau %s",
	[220119] = "Tướng quân ngài không phải vẫn chưa tạo binh khí? Chế tạo + cường hóa, chiến lực tăng vọt!\nVào giao diện binh khí",
	[135209] = "Bạn đã tiêu %s Vàng, tiêu thêm %s Vàng được nhận quà kế tiếp!",
	[215134] = "Báo danh trận chính thức:\n1.Có 4 bãi chiến Diễn Võ, mỗi bãi được báo danh 5 người.\n2.Nếu thực lực của người báo danh sau cao hơn, sẽ thay thế người có thực lực thấp nhất .\nBáo danh Tự Do Đối Chiến:\n1.Người có thần binh trên Lv50 có thể báo danh.\n2.Sau khi bắt đầu trận chính thức có thể báo danh, kéo dài 30p.\n3.Đủ 5 người sẽ bắt đầu bắt cặp đối thủ\n4.Khi nước địch cũng có đội đang bắt cặp, sẽ đấu với đội đó.\nPhán định thắng bại:\n1.Đánh thắng mỗi bãi chiến được 1 tích điểm, thất bại hoặc hòa 0đ.\n2.Khi tất cả quốc gia kết thúc toàn bộ chiến đấu, căn cứ tích điểm để chốt hạng.\nPhần thưởng:\n1.Các tướng tham gia trận chính thức căn cứ thắng thua nhận thưởng.\n2.Tham gia Tự Do Đối Chiến sẽ căn cứ thắng thua nhận thưởng.\n3.Không tham gia chiến đấu, nhưng khi diễn ra Quốc Chiến có người chơi giết địch, căn cứ kết quả thắng thua cuối cùng để nhận thưởng.\n4.Top 1 Diễn Võ được 3 điểm Quốc Gia, Top 2 và 3 được 1đ.",
	[95057] = "Phần thưởng danh hiệu:",
