	["216406_qxgj"] = "Viên",
	["216427_qxgj"] = "%s sau kết thúc chiến đấu",
	[390464] = "1. Tài nguyên quốc khố mỗi ngày sẽ phát tiền lãi cho người chơi toàn quốc, tiến hành viễn chinh liên máy chủ có thể mở rộng quốc khố. \n2. Khi viễn chinh liên máy chủ, toàn thể bổn quốc vào trong thế giới của máy chủ mục tiêu viễn chinh, đối kháng với ba nước trong máy chủ. \n3. Những thành trì chủ chốt của máy chủ mục tiêu viễn chinh đều có quốc khố, mỗi lần chếm 1 thành trình chủ chốt có thể nhận toàn bộ tài nguyên quốc khố. \n4. Trong máy chủ được viễn chinh cũng có thành trì chủ chốt của phe ta, lưu trữ tài nguyên quốc khố nước ta. Nếu thành trì chủ chốt phe ta bị kẻ địch công phá, tài nguyên quốc khố cũng sẽ bị địch cướp.",
