	[112004] = "Cấp bậc",
	[137118] = "Báo danh:\n1. Lôi Đài tổng cộng tiến hành 3 vòng đấu, mỗi lôi đài tối đa 5 người báo danh.\n2. Hơn 5 người báo danh, người có thực lực cao sẽ thay thế người có thực lực thấp hơn ra trận.\n\nTham chiến:\n1. Đánh luân phiên 5V5, người mới ra trận có thể bố trận.\n2. Bên nào thua hết 5 người trước, bên còn lại sẽ thắng, được 1 điểm Quốc Gia.\n3. Sau khi kết thúc 3 vòng, căn cứ tích điểm của 3 nước để chốt xếp hạng.\n\nHỏa Kế:\n1. 5 người trong mỗi vòng đấu dùng chung 1 lần Hỏa Kế.\n2. Nếu Lôi Đài vòng trước thất bại, số lần thi đấu vòng sau sẽ cộng 1.\n\nPhần thưởng:\n1. Người tham chiến dựa vào thứ hạng nhận nhiều phần thưởng.\n2. Người quan chiến dựa vào thứ hạng quốc gia nhận ít phần thưởng.\n3. Phần thưởng thắng thua của mỗi lần, tối đa nhận được 5%% EXP của LV hiện tại.",
